// Generated by scripts/track_layouts.py into src/data/tracks/<circuitId>.json
export interface TrackCorner {
  number: string;
  at: [number, number];
  label: [number, number];
}

export interface TrackLayout {
  circuitId: string;
  year: number; // qualifying the reference lap comes from
  driver: string; // three-letter code
  lapTime: number; // seconds
  drsYear: number | null; // DRS was abolished in 2026, so zones come from an earlier season
  viewBox: [number, number, number, number];
  points: [number, number][]; // evenly spaced along the lap, starting at the finish line
  speed: number[]; // km/h at each point
  sectors: [number, number]; // point indices where sectors 1 and 2 end
  drsZones: [number, number][]; // [start, end] point indices; start > end when a zone crosses the finish line
  corners: TrackCorner[];
}
